  if (!Object.is(m.class, want.class)) return ".class";
  if (!Object.is(m.team, want.team)) return ".team";
  if (!sameVec(m.position, want.position)) return ".position";
  if (!sameVec(m.velocity, want.velocity)) return ".velocity";
  if (!Object.is(m.yaw, want.yaw)) return ".yaw";
  if (!Object.is(m.pitch, want.pitch)) return ".pitch";
