export function exportReconDroid(o, cx) {
  let v = cx.seen.get(o);
  if (v) return v;
  v = {};
  cx.seen.set(o, v);
  v.$id = cx.ref("reconDroid", o);
  v.context = cx.ref("reconContext", o.context);
  v.owner = exportF3UnitKey(o.owner, cx);
  v.launchOwner = cx.ref("ownerSnapshot", o.launchOwner);
  v.weapon = o.weapon;
  v.class = o.class;
  v.team = o.team;
  v.position = o.position.clone();
  v.velocity = o.velocity.clone();
  v.yaw = o.yaw;
  v.pitch = o.pitch;
  v.health = o.health;
  v.dead = o.dead;
  v.eye = o.eye.clone();
  v.aim = o.aim.clone();
  v.target = o.target.clone();
  v.countdown = o.countdown;
  v.salvo = ((x) => (x === null || x === undefined ? x : exportReconSalvo(x, cx)))(o.salvo);
  v.weapons = o.weapons.map((x) => exportWeapon(x, cx));
  v.selected = [...o.selected];
  return v;
}
